import heapq
class Solution:
    def minOperations(self, s):
        letters = {c for c in s if c != 'a'}
        heap = [(-ord(c), c) for c in letters]
        heapq.heapify(heap)
        ops = 0
        while heap:
            _, c = heapq.heappop(heap)
            nc = 'a' if c == 'z' else chr(ord(c) + 1)
            ops += 1
            if nc != 'a' and all(x != nc for _, x in heap):
                heapq.heappush(heap, (-ord(nc), nc))
        return ops

