class Solution {
public:
    int minOperations(string s) {
        priority_queue<char> pq;
        unordered_set<char> in;
        for (char c : s) if (c != 'a' && in.insert(c).second) pq.push(c);
        int ops = 0;
        while (!pq.empty()) {
            char c = pq.top(); pq.pop();
            char nc = (c == 'z') ? 'a' : (char)(c + 1);
            ops++;
            if (nc != 'a' && !in.count(nc)) { in.insert(nc); pq.push(nc); }
        }
        return ops;
    }
};

