class Solution {
    public int minOperations(String s) {
        PriorityQueue<Character> pq = new PriorityQueue<>(Collections.reverseOrder());
        Set<Character> in = new HashSet<>();
        for (char c : s.toCharArray()) if (c != 'a' && in.add(c)) pq.add(c);
        int ops = 0;
        while (!pq.isEmpty()) {
            char c = pq.poll();
            char nc = (c == 'z') ? 'a' : (char)(c + 1);
            ops++;
            if (nc != 'a' && in.add(nc)) pq.add(nc);
        }
        return ops;
    }
}

