var minOperations = function(s) {
    const letters = [...new Set([...s].filter(c => c !== 'a'))];
    const heap = letters.map(c => -c.charCodeAt(0));
    const has = new Set(letters);
    let ops = 0;
    while (heap.length) {
        const c = String.fromCharCode(-heap[0]);
        heap[0] = heap[heap.length - 1]; heap.pop();
        if (heap.length) {
            let i = 0;
            for (;;) { let l = 2*i+1, r = l+1, m = i;
                if (l < heap.length && heap[l] > heap[m]) m = l;
                if (r < heap.length && heap[r] > heap[m]) m = r;
                if (m === i) break; [heap[i], heap[m]] = [heap[m], heap[i]; i = m; }
        }
        const nc = c === 'z' ? 'a' : String.fromCharCode(c.charCodeAt(0) + 1);
        ops++;
        if (nc !== 'a' && !has.has(nc)) { has.add(nc); heap.push(-nc.charCodeAt(0));
            let i = heap.length - 1;
            while (i > 0) { const p = (i - 1) >> 1; if (heap[p] >= heap[i]) break; [heap[p], heap[i]] = [heap[i], heap[p]]; i = p; }
        }
    }
    return ops;
};
